      // --- MOVE UP ---
      if (direction === 'up') {
          // 1. Calculate distance to neighbor (Gap)
          const myMargin = product.customMarginTop || 0;

          // 2. Logic Split: Nudge vs Interact

          // CASE A: NUDGE UP (Zero-Sum Physics) - Reverse Snowplow Fix
