                   updates.push({ id: nextItem.id, field: 'customMarginTop', value: nextMargin + NUDGE_STEP });
              }
              onUpdateProducts?.(updates);
              return;
          }

          // CASE B: COLLISION / INTERACTION (Gap is small - Encostou no item de cima)
          if (neighbor && neighbor.type === 'product' && neighbor.product) {
               // Sub-case: Neighbor is Free Text -> Swap
               if (neighbor.product.isFreeText) {
                   if (onUpdateProducts && onCommitProductOrder) {
                       const neighborMargin = neighbor.product.customMarginTop || 0;
                       const currentOrder = groupedProducts[catName].map(p => p.id);
                       const idx1 = currentOrder.indexOf(id);
                       const idx2 = currentOrder.indexOf(neighbor.id);
                       const newOrder = [...currentOrder];
                       [newOrder[idx1], newOrder[idx2]] = [newOrder[idx2], newOrder[idx1]];

                       onUpdateProducts([
                           { id: product.id, field: 'customMarginTop', value: neighborMargin },
                           { id: neighbor.id, field: 'customMarginTop', value: myMargin },
                           { id: product.id, field: 'category', value: neighbor.category },
                           { id: neighbor.id, field: 'category', value: catName }
                       ]);
                       onCommitProductOrder(catName, newOrder);
                   }
                   return;
               }

               // Fix 2: Bottom-Up Category Entry (Unlock)
               // Tentativa de entrar em Categoria: O vizinho de cima é um Produto Real em uma Categoria Real
               const targetCat = neighbor.category;
               if (!targetCat.startsWith(FREE_TEXT_PREFIX)) {
                   if (onUpdateProducts && onCommitProductOrder) {
                       // 1. Move FreeText INTO the category (Append)
                       const currentOrder = groupedProducts[targetCat]?.map(p => p.id) || [];
                       const neighborIndex = currentOrder.indexOf(neighbor.id);
                       const newOrder = [...currentOrder];

                       // Insere APÓS o vizinho (Lógica de Append)
                       if (neighborIndex !== -1) {
                           newOrder.splice(neighborIndex + 1, 0, product.id);
                       } else {
                           newOrder.push(product.id);
                       }

                       // 2. Atualiza Dados: Adota a categoria e reseta a margem para o padrão da lista
                       onUpdateProducts([
                           { id: product.id, field: 'category', value: targetCat },
                           { id: product.id, field: 'customMarginTop', value: STANDARD_GAP } 
                       ]);

                       onCommitProductOrder(targetCat, newOrder);
                   }
                   return;
               }
          }

          // Case C: Neighbor is Header (Top Exit)
          if (neighbor && neighbor.type === 'header') {
               // Exiting Current Category (Top Exit) -> Create Ghost Zone Above
               if (onStyleUpdate && onUpdateProduct) {
                    const newGhostCat = `${FREE_TEXT_PREFIX}${crypto.randomUUID()}`;
                    onStyleUpdate(prev => {
                        const cats = [...(prev.customCategoryOrder || sortedCategories)];
                        const idx = cats.indexOf(neighbor.category);
                        if (idx !== -1) cats.splice(idx, 0, newGhostCat);
                        return { ...prev, customCategoryOrder: cats, name: 'Custom' };
                    });
                    onUpdateProduct(id, 'category', newGhostCat);
               }
               return;
          }
      }

